# qx2_geom_seq :: (1, 2, 5)
def qx2_geom_seq(a, r, n):
    out = [a]
    for _ in range(n - 1):
        a *= r
        out.append(a)
    return out

if __name__ == '__main__':
    print(qx2_geom_seq((1, 2, 5)))

